-- SELECT/catalog only; execute after both operational bundles, never SQL fixtures.
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path = pg_catalog;
SELECT current_database() AS database,current_user AS role,
       current_setting('transaction_read_only') AS read_only;
WITH actual AS (SELECT c.relname AS table_name,pg_get_userbyid(c.relowner) AS owner,a.attname AS column_name,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull AS not_null,COALESCE(pg_get_expr(d.adbin,d.adrelid),'') AS default_expr,a.attidentity AS identity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='dojo' AND c.relname IN ('analytics_run','analytics_progress','analytics_day','analytics_page_day','analytics_stage') ORDER BY c.relname,a.attname)
SELECT 'columns' AS check_name, COALESCE(jsonb_agg(to_jsonb(actual) ORDER BY table_name,column_name), '[]'::jsonb) = $expected$[{"table_name":"analytics_day","owner":"tullyelly_admin","column_name":"collected_at","type":"timestamp with time zone","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_day","owner":"tullyelly_admin","column_name":"day","type":"date","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_day","owner":"tullyelly_admin","column_name":"pageviews","type":"bigint","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_day","owner":"tullyelly_admin","column_name":"project_id","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_day","owner":"tullyelly_admin","column_name":"run_id","type":"bigint","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_day","owner":"tullyelly_admin","column_name":"status","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_day","owner":"tullyelly_admin","column_name":"visitors","type":"bigint","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_page_day","owner":"tullyelly_admin","column_name":"day","type":"date","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_page_day","owner":"tullyelly_admin","column_name":"pageviews","type":"bigint","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_page_day","owner":"tullyelly_admin","column_name":"project_id","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_page_day","owner":"tullyelly_admin","column_name":"request_path","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_page_day","owner":"tullyelly_admin","column_name":"visitors","type":"bigint","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_progress","owner":"tullyelly_admin","column_name":"available_from","type":"date","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_progress","owner":"tullyelly_admin","column_name":"end_day","type":"date","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_progress","owner":"tullyelly_admin","column_name":"lane","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_progress","owner":"tullyelly_admin","column_name":"next_day","type":"date","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_progress","owner":"tullyelly_admin","column_name":"project_id","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_progress","owner":"tullyelly_admin","column_name":"start_day","type":"date","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"error_code","type":"text","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"finished_at","type":"timestamp with time zone","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"id","type":"bigint","not_null":true,"default_expr":"","identity":"a"},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"lane","type":"text","not_null":false,"default_expr":"","identity":""},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"processed_days","type":"integer","not_null":true,"default_expr":"0","identity":""},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"project_id","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"request_count","type":"integer","not_null":true,"default_expr":"0","identity":""},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"started_at","type":"timestamp with time zone","not_null":true,"default_expr":"CURRENT_TIMESTAMP","identity":""},{"table_name":"analytics_run","owner":"tullyelly_admin","column_name":"status","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_stage","owner":"tullyelly_admin","column_name":"day","type":"date","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_stage","owner":"tullyelly_admin","column_name":"pageviews","type":"bigint","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_stage","owner":"tullyelly_admin","column_name":"project_id","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_stage","owner":"tullyelly_admin","column_name":"request_path","type":"text","not_null":true,"default_expr":"","identity":""},{"table_name":"analytics_stage","owner":"tullyelly_admin","column_name":"visitors","type":"bigint","not_null":true,"default_expr":"","identity":""}]$expected$::jsonb AS matches_release_contract FROM actual;
WITH actual AS (SELECT c.relname AS table_name,k.conname AS name,k.contype AS type,k.convalidated AS validated,pg_get_constraintdef(k.oid) AS definition FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_constraint k ON k.conrelid=c.oid WHERE n.nspname='dojo' AND c.relname IN ('analytics_run','analytics_progress','analytics_day','analytics_page_day','analytics_stage') ORDER BY c.relname,k.conname)
SELECT 'constraints' AS check_name, COALESCE(jsonb_agg(to_jsonb(actual) ORDER BY table_name,name), '[]'::jsonb) = $expected$[{"table_name":"analytics_day","name":"analytics_day_check","type":"c","validated":true,"definition":"CHECK ((((status = ANY (ARRAY['complete'::text, 'zero'::text])) AND (pageviews IS NOT NULL) AND (visitors IS NOT NULL)) OR ((status <> ALL (ARRAY['complete'::text, 'zero'::text])) AND (pageviews IS NULL) AND (visitors IS NULL))))"},{"table_name":"analytics_day","name":"analytics_day_check1","type":"c","validated":true,"definition":"CHECK (((status <> 'zero'::text) OR ((pageviews = 0) AND (visitors = 0))))"},{"table_name":"analytics_day","name":"analytics_day_pageviews_check","type":"c","validated":true,"definition":"CHECK ((pageviews >= 0))"},{"table_name":"analytics_day","name":"analytics_day_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (project_id, day)"},{"table_name":"analytics_day","name":"analytics_day_run_id_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (run_id) REFERENCES dojo.analytics_run(id)"},{"table_name":"analytics_day","name":"analytics_day_status_check","type":"c","validated":true,"definition":"CHECK ((status = ANY (ARRAY['incomplete'::text, 'complete'::text, 'zero'::text, 'unavailable'::text, 'api_failure'::text])))"},{"table_name":"analytics_day","name":"analytics_day_visitors_check","type":"c","validated":true,"definition":"CHECK ((visitors >= 0))"},{"table_name":"analytics_page_day","name":"analytics_page_day_pageviews_check","type":"c","validated":true,"definition":"CHECK ((pageviews >= 0))"},{"table_name":"analytics_page_day","name":"analytics_page_day_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (project_id, day, request_path)"},{"table_name":"analytics_page_day","name":"analytics_page_day_project_id_day_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (project_id, day) REFERENCES dojo.analytics_day(project_id, day)"},{"table_name":"analytics_page_day","name":"analytics_page_day_request_path_check","type":"c","validated":true,"definition":"CHECK ((request_path ~~ '/%'::text))"},{"table_name":"analytics_page_day","name":"analytics_page_day_visitors_check","type":"c","validated":true,"definition":"CHECK ((visitors >= 0))"},{"table_name":"analytics_progress","name":"analytics_import_range","type":"c","validated":true,"definition":"CHECK ((((start_day IS NULL) AND (end_day IS NULL) AND (available_from IS NULL)) OR ((lane = 'backfill'::text) AND (start_day IS NOT NULL) AND (end_day IS NOT NULL) AND (available_from IS NOT NULL) AND (start_day <= end_day) AND (start_day >= available_from))))"},{"table_name":"analytics_progress","name":"analytics_progress_lane_check","type":"c","validated":true,"definition":"CHECK ((lane = ANY (ARRAY['daily'::text, 'backfill'::text])))"},{"table_name":"analytics_progress","name":"analytics_progress_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (project_id, lane)"},{"table_name":"analytics_run","name":"analytics_run_lane_check","type":"c","validated":true,"definition":"CHECK ((lane = ANY (ARRAY['daily'::text, 'backfill'::text])))"},{"table_name":"analytics_run","name":"analytics_run_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"table_name":"analytics_run","name":"analytics_run_processed_days_check","type":"c","validated":true,"definition":"CHECK ((processed_days >= 0))"},{"table_name":"analytics_run","name":"analytics_run_request_count_check","type":"c","validated":true,"definition":"CHECK ((request_count >= 0))"},{"table_name":"analytics_run","name":"analytics_run_status_check","type":"c","validated":true,"definition":"CHECK ((status = ANY (ARRAY['running'::text, 'complete'::text, 'bounded'::text, 'failed'::text, 'interrupted'::text])))"},{"table_name":"analytics_stage","name":"analytics_stage_pageviews_check","type":"c","validated":true,"definition":"CHECK ((pageviews >= 0))"},{"table_name":"analytics_stage","name":"analytics_stage_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (project_id, day, request_path)"},{"table_name":"analytics_stage","name":"analytics_stage_request_path_check","type":"c","validated":true,"definition":"CHECK ((request_path ~~ '/%'::text))"},{"table_name":"analytics_stage","name":"analytics_stage_visitors_check","type":"c","validated":true,"definition":"CHECK ((visitors >= 0))"}]$expected$::jsonb AS matches_release_contract FROM actual;
SELECT filename,checksum,checksum_algorithm,status,applied_at,attempted_at,execution_ms,
       error_message IS NOT NULL AS has_error
FROM dojo.schema_migration
WHERE filename IN ('076_create_analytics_archive.sql','077_analytics_operations.sql')
ORDER BY filename;
SELECT a.slug AS app,f.key,f.enabled,r.name AS role,g.effect
FROM dojo.authz_feature f JOIN dojo.authz_app a ON a.id=f.app_id
LEFT JOIN dojo.authz_role_feature g ON g.feature_id=f.id
LEFT JOIN dojo.authz_role r ON r.id=g.role_id
WHERE f.key='admin.analytics.manage' ORDER BY r.name;
SELECT p.proname,pg_get_userbyid(p.proowner) AS owner,
       pg_get_functiondef(p.oid) AS definition
FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
WHERE n.nspname='dojo' AND p.proname IN ('authz_bump_revision','authz_get_revision');
SELECT c.relname,c.relkind,pg_get_userbyid(c.relowner) AS owner
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='dojo' AND c.relname LIKE 'analytics_%'
ORDER BY c.relname;
SELECT tablename,indexname,indexdef FROM pg_indexes
WHERE schemaname='dojo' AND tablename IN
  ('analytics_run','analytics_progress','analytics_day','analytics_page_day','analytics_stage','schema_migration')
ORDER BY tablename,indexname;
ROLLBACK;
